/// A bearer token goes only to https, only to the host the download began at, and only when there is one.
#[test]
fn a_token_is_sent_only_over_https_to_the_first_host() {
    let u = |s: &str| Url::parse(s).unwrap();
    let first = u("https://huggingface.co/x/model.bin");
    assert_eq!(bearer(Some(" hf_abc \n"), &first, "huggingface.co"), Some("hf_abc"));
    // the storage host a redirect leads to, plain http, no token, an empty one
    assert_eq!(bearer(Some("hf_abc"), &u("https://cdn-lfs.example/x"), "huggingface.co"), None);
    assert_eq!(bearer(Some("hf_abc"), &u("http://huggingface.co/x"), "huggingface.co"), None);
    assert_eq!(bearer(None, &first, "huggingface.co"), None);
    assert_eq!(bearer(Some("  "), &first, "huggingface.co"), None);
    // a caller that names no variable sends nothing, whatever the environment holds
    assert!(Options::default().token_env.is_none());
}

#[test]
fn exact_url_keeps_query_and_owned_catalog_values() {
    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let url = format!("http://{}/download?file=weights&sig=secret", listener.local_addr().unwrap());
    let worker = std::thread::spawn(move || {
        let (mut socket, _) = listener.accept().unwrap();
        let mut reader = BufReader::new(socket.try_clone().unwrap());
        let mut request = String::new();
        reader.read_line(&mut request).unwrap();
        assert_eq!(request.trim(), "GET /download?file=weights&sig=secret HTTP/1.1");
        loop {
            let mut line = String::new();
            if reader.read_line(&mut line).unwrap() == 0 || line.trim().is_empty() {
                break;
            }
        }
        socket.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 3\r\nConnection: close\r\n\r\nabc").unwrap();
    });
    let name = String::from("catalog.onnx");
    let hash = sha_hex(b"abc");
    let spec = FileSpec { name: &name, size: Some(3), sha256: Some(&hash), max: 3 };
    let dir = tmp("exact");
    let mut progress = Vec::new();
    download_url(&spec, &url, &dir, &quick(), &AtomicBool::new(false), &mut |p| progress.push(p.clone())).unwrap();
    worker.join().unwrap();
    assert_eq!(std::fs::read(dir.join(name)).unwrap(), b"abc");
    assert!(progress.iter().all(|p| !p.mirror.contains("secret")));
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn hostile_file_specs_are_rejected_before_touching_disk() {
    let dir = tmp("invalid");
    let base = FileSpec { name: "valid.onnx", size: Some(1), sha256: None, max: 1 };
    let cancel = AtomicBool::new(false);
    for name in ["", ".hidden", "../escape", "a/b", "a\\b", "C:escape", "bad\nname", "trailing.", "CON.onnx", "a.part"] {
        let spec = FileSpec { name, ..base.clone() };
        assert!(matches!(run(&[spec], &[], &dir, &cancel).0, Err(DownloadError::Invalid(_))), "{name}");
        assert!(!dir.exists());
    }
    for spec in [
        FileSpec { max: 0, ..base.clone() },
        FileSpec { size: Some(0), ..base.clone() },
        FileSpec { size: Some(2), ..base.clone() },
        FileSpec { sha256: Some("not a SHA"), ..base.clone() },
    ] {
        assert!(matches!(run(&[spec], &[], &dir, &cancel).0, Err(DownloadError::Invalid(_))));
        assert!(!dir.exists());
    }
    let huge = FileSpec { size: Some(u64::MAX), max: u64::MAX, ..base.clone() };
    let other = FileSpec { name: "other.onnx", ..huge.clone() };
    for specs in [vec![huge, other], vec![base.clone(); 257], vec![base.clone(), base]] {
        assert!(matches!(run(&specs, &[], &dir, &cancel).0, Err(DownloadError::Invalid(_))));
        assert!(!dir.exists());
    }
}

//! Offline reverse geocoding: a GPS position → Sublocation / City / State / Country, from the
//! GeoNames dump (CC-BY 4.0, "GeoNames, geonames.org"). See README.md.
//!
//! Sources: GeoNames dump readme (prose); haversine (textbook); cell index own design.
#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

pub mod unzip;

use std::collections::HashMap;
use std::path::Path;

use serde::Serialize;

/// Lookups farther than this from any place find nothing.
pub const MAX_KM: f64 = 50.0;
/// The files the engine downloads (the first comes zipped as `cities15000.zip`).
pub const GEONAMES_FILES: [&str; 3] = ["cities15000.txt", "admin1CodesASCII.txt", "countryInfo.txt"];
/// The zip holding [`GEONAMES_FILES`]`[0]`.
pub const GEONAMES_ZIP: &str = "cities15000.zip";
pub const GEONAMES_BASE: &str = "https://download.geonames.org/export/dump/";
pub const GEONAMES_ATTRIBUTION: &str = "Place names: GeoNames (geonames.org), CC-BY 4.0";
/// Places kept from a dataset (cities15000 has ~33 000; cities500 ~200 000).
const MAX_PLACES: usize = 2_000_000;
/// Largest name kept (GeoNames names are short; anything longer is junk).
const MAX_NAME: usize = 200;
const EARTH_RADIUS_M: f64 = 6_371_008.8;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GeocodeError {
    /// The place names aren't there (not downloaded yet) or can't be read.
    Missing(String),
    /// The data is not what it should be.
    Invalid(String),
}

impl std::fmt::Display for GeocodeError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            GeocodeError::Missing(e) | GeocodeError::Invalid(e) => f.write_str(e),
        }
    }
}

impl std::error::Error for GeocodeError {}

/// A position in degrees.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct LatLon {
    pub lat: f64,
    pub lon: f64,
}

impl LatLon {
    pub fn new(lat: f64, lon: f64) -> LatLon {
        LatLon { lat, lon }
    }

    /// Finite and on the globe.
    pub fn is_valid(self) -> bool {
        self.lat.is_finite() && self.lon.is_finite() && self.lat.abs() <= 90.0 && self.lon.abs() <= 180.0
    }
}

/// Great-circle distance in metres (haversine). NaN in, NaN out.
pub fn distance_m(a: LatLon, b: LatLon) -> f64 {
    let (p1, p2) = (a.lat.to_radians(), b.lat.to_radians());
    let dp = p2 - p1;
    let dl = (b.lon - a.lon).to_radians();
    let h = (dp / 2.0).sin().powi(2) + p1.cos() * p2.cos() * (dl / 2.0).sin().powi(2);
    2.0 * EARTH_RADIUS_M * h.clamp(0.0, 1.0).sqrt().asin()
}

/// What a lookup fills in (empty strings: unknown).
#[derive(Clone, Debug, Default, PartialEq, Serialize)]
pub struct Place {
    /// Below city level. GeoNames' city list has none, so offline lookups leave it empty.
    pub sublocation: String,
    pub city: String,
    pub state: String,
    pub country: String,
    /// ISO 3166-1 alpha-2, upper case.
    pub iso: String,
    /// Metres from the position to the place.
    pub distance: f64,
}

#[derive(Clone, Debug)]
struct City {
    name: String,
    at: LatLon,
    country: String,
    admin1: String,
}

/// An offline GeoNames index: places bucketed by 1° cells.
#[derive(Clone, Debug, Default)]
pub struct GeoNames {
    cities: Vec<City>,
    cells: HashMap<(i32, i32), Vec<u32>>,
    admin1: HashMap<String, String>,
    countries: HashMap<String, String>,
}

fn cell(p: LatLon) -> (i32, i32) {
    // valid positions only: |lat| ≤ 90, |lon| ≤ 180, so the casts are in range
    (p.lat.floor() as i32, p.lon.floor() as i32)
}

fn short(s: &str) -> String {
    s.trim().chars().take(MAX_NAME).collect()
}

impl GeoNames {
    /// From the dump's text: `cities` (tab-separated, the `cities*.txt` layout), and optionally
    /// `admin1CodesASCII.txt` and `countryInfo.txt`. Bad lines are skipped.
    pub fn parse(cities: &str, admin1: Option<&str>, countries: Option<&str>) -> GeoNames {
        let mut g = GeoNames::default();
        for line in cities.lines() {
            if g.cities.len() >= MAX_PLACES {
                break;
            }
            let f: Vec<&str> = line.split('\t').collect();
            // columns: 1 name, 4 latitude, 5 longitude, 8 country code, 10 admin1 code
            let (Some(name), Some(lat), Some(lon), Some(cc)) = (f.get(1), f.get(4), f.get(5), f.get(8)) else { continue };
            let (Ok(lat), Ok(lon)) = (lat.trim().parse::<f64>(), lon.trim().parse::<f64>()) else { continue };
            let at = LatLon::new(lat, lon);
            let name = short(name);
            if !at.is_valid() || name.is_empty() {
                continue;
            }
            let Ok(i) = u32::try_from(g.cities.len()) else { break };
            g.cells.entry(cell(at)).or_default().push(i);
            g.cities.push(City { name, at, country: short(cc).to_ascii_uppercase(), admin1: f.get(10).map(|s| short(s)).unwrap_or_default() });
        }
        for line in admin1.unwrap_or("").lines() {
            let mut f = line.split('\t');
            if let (Some(code), Some(name)) = (f.next(), f.next()) {
                g.admin1.insert(short(code), short(name));
            }
        }
        for line in countries.unwrap_or("").lines().filter(|l| !l.starts_with('#')) {
            let f: Vec<&str> = line.split('\t').collect();
            if let (Some(iso), Some(name)) = (f.first(), f.get(4)) {
                g.countries.insert(short(iso).to_ascii_uppercase(), short(name));
            }
        }
        g
    }

    /// Load from a folder holding [`GEONAMES_FILES`] (the last two are optional: without them
    /// states stay blank and countries are ISO codes).
    pub fn load(dir: &Path) -> Result<GeoNames, GeocodeError> {
        let read = |n: &str| std::fs::read(dir.join(n)).map(|b| String::from_utf8_lossy(&b).into_owned());
        let cities = read(GEONAMES_FILES[0]).map_err(|e| GeocodeError::Missing(format!("the place names aren't downloaded ({e})")))?;
        let g = GeoNames::parse(&cities, read(GEONAMES_FILES[1]).ok().as_deref(), read(GEONAMES_FILES[2]).ok().as_deref());
        if g.is_empty() {
            return Err(GeocodeError::Invalid("the place names file holds no places".into()));
        }
        Ok(g)
    }

    pub fn len(&self) -> usize {
        self.cities.len()
    }

    pub fn is_empty(&self) -> bool {
        self.cities.is_empty()
    }

    /// The nearest place within [`MAX_KM`]; `None` for an invalid position or open country.
    pub fn reverse(&self, p: LatLon) -> Option<Place> {
        if !p.is_valid() {
            return None;
        }
        let (cy, cx) = cell(p);
        let mut best: Option<(f64, &City)> = None;
        // ±1° covers 50 km everywhere except very near the poles (where there are no cities)
        for dy in -1..=1 {
            for dx in -1..=1 {
                let mut x = cx + dx;
                if x < -180 {
                    x += 360;
                } else if x >= 180 {
                    x -= 360;
                }
                for &i in self.cells.get(&(cy + dy, x)).into_iter().flatten() {
                    let Some(c) = self.cities.get(i as usize) else { continue };
                    let d = distance_m(p, c.at);
                    if best.is_none_or(|(b, _)| d < b) {
                        best = Some((d, c));
                    }
                }
            }
        }
        let (d, c) = best?;
        (d <= MAX_KM * 1000.0).then(|| Place {
            sublocation: String::new(),
            city: c.name.clone(),
            state: self.admin1.get(&format!("{}.{}", c.country, c.admin1)).cloned().unwrap_or_default(),
            country: self.countries.get(&c.country).cloned().unwrap_or_else(|| c.country.clone()),
            iso: c.country.clone(),
            distance: d.round(),
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const CITIES: &str = "2988507\tParis\tParis\t\t48.85341\t2.3488\tP\tPPLC\tFR\t\t11\t75\t\t\t2138551\t\t42\tEurope/Paris\t2024-01-01\n\
                          2643743\tLondon\tLondon\t\t51.50853\t-0.12574\tP\tPPLC\tGB\t\tENG\t\t\t\t8961989\t\t25\tEurope/London\t2024-01-01\n\
                          bad line\n\
                          1\tNowhere\tx\t\tNaN\t0\tP\tP\tXX\n\
                          2\tFar\tx\t\t500\t0\tP\tP\tXX\n\
                          3\tInf\tx\t\tinf\t-inf\tP\tP\tXX\n";

    #[test]
    fn nearest_place() {
        let g = GeoNames::parse(CITIES, Some("FR.11\tÎle-de-France\nGB.ENG\tEngland\n"), Some("#ISO\tx\nFR\tFRA\t250\tFR\tFrance\n"));
        assert_eq!(g.len(), 2);
        let p = g.reverse(LatLon::new(48.86, 2.34)).unwrap();
        assert_eq!((p.city.as_str(), p.state.as_str(), p.country.as_str(), p.iso.as_str()), ("Paris", "Île-de-France", "France", "FR"));
        assert!(p.distance > 0.0 && p.distance < 2000.0);
        // no countryInfo row: the ISO code stands in
        let l = g.reverse(LatLon::new(51.5, -0.1)).unwrap();
        assert_eq!((l.city.as_str(), l.state.as_str(), l.country.as_str()), ("London", "England", "GB"));
        // open sea
        assert!(g.reverse(LatLon::new(0.0, 0.0)).is_none());
    }

    #[test]
    fn hostile_positions_find_nothing() {
        let g = GeoNames::parse(CITIES, None, None);
        for (la, lo) in [(f64::NAN, 0.0), (0.0, f64::NAN), (f64::INFINITY, 0.0), (91.0, 0.0), (0.0, -180.5), (-1e300, 1e300)] {
            assert!(g.reverse(LatLon::new(la, lo)).is_none(), "{la}, {lo}");
        }
        // the poles and the antimeridian are fine
        assert!(g.reverse(LatLon::new(90.0, 180.0)).is_none());
        assert!(g.reverse(LatLon::new(-90.0, -180.0)).is_none());
        assert!(GeoNames::default().reverse(LatLon::new(48.86, 2.34)).is_none());
    }

    #[test]
    fn across_the_antimeridian() {
        let fiji = GeoNames::parse("1\tX\tX\t\t-17.0\t179.9\tP\tP\tFJ\t\t\n", None, None);
        assert_eq!(fiji.reverse(LatLon::new(-17.0, -179.95)).unwrap().city, "X");
    }

    #[test]
    fn junk_text_parses_to_nothing() {
        let g = GeoNames::parse("\t\t\t\t\t\n\u{0}\t\u{feff}\n", Some("\n\t\n"), Some("x"));
        assert!(g.is_empty());
        let long = format!("1\t{}\tx\t\t1\t1\tP\tP\tXX\n", "a".repeat(10_000));
        assert_eq!(GeoNames::parse(&long, None, None).reverse(LatLon::new(1.0, 1.0)).unwrap().city.len(), MAX_NAME);
    }

    #[test]
    fn load_from_a_folder() {
        let dir = std::env::temp_dir().join(format!("lightcraft-geocode-load-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        assert!(matches!(GeoNames::load(&dir), Err(GeocodeError::Missing(_))));
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join(GEONAMES_FILES[0]), "junk").unwrap();
        assert!(matches!(GeoNames::load(&dir), Err(GeocodeError::Invalid(_))));
        std::fs::write(dir.join(GEONAMES_FILES[0]), CITIES).unwrap();
        std::fs::write(dir.join(GEONAMES_FILES[2]), "GB\tGBR\t826\tUK\tUnited Kingdom\n").unwrap();
        let g = GeoNames::load(&dir).unwrap();
        assert_eq!(g.reverse(LatLon::new(51.5, -0.1)).unwrap().country, "United Kingdom");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

//! Device-memory bookkeeping: a view's stages are counted, released buffers are pooled within
//! the pool limit, and trimming frees them. Skips when no GPU adapter exists.

use std::sync::Arc;

use lightcraft_develop::DevelopSettings;
use lightcraft_pipeline::{RenderRequest, SourceInfo, StageCache};

#[test]
fn stages_are_counted_and_the_pool_is_bounded_and_trimmed() {
    if !lightcraft_gpu::available() {
        eprintln!("skipped: no GPU adapter");
        return;
    }
    let limit = 64u64 << 20;
    lightcraft_gpu::set_pool_limit(limit);
    let info = SourceInfo { raw: true, ..Default::default() };
    let mut s = DevelopSettings::default();
    s.effects.clarity = 30.0;
    let stages = StageCache::default();
    // photos of slightly different sizes, like stepping through a library
    for (i, (w, h)) in [(1200usize, 800usize), (1190, 810), (1210, 790), (800, 1200)].into_iter().enumerate() {
        let src = Arc::new(lightcraft_scenes::demo_library()[i].render(w, h));
        let r = lightcraft_gpu::render(&src, &info, &s, &RenderRequest::fit(w, h), Some(&stages)).expect("gpu render");
        assert_eq!((r.image.width, r.image.height), (w, h));
        let m = lightcraft_gpu::memory();
        assert!(m.pooled <= limit, "pool {} over its limit", m.pooled);
        assert_eq!(m.retired, 0, "a finished render leaves nothing retired");
    }
    let held = lightcraft_gpu::stage_bytes(&stages);
    assert!(held >= 1200 * 800 * 3 * 4, "the view's stages hold at least its resampled source: {held}");
    let before = lightcraft_gpu::memory().allocated;
    stages.clear();
    let m = lightcraft_gpu::memory();
    assert_eq!(lightcraft_gpu::stage_bytes(&stages), 0);
    assert!(m.pooled <= limit && m.allocated <= before);
    lightcraft_gpu::trim_pool(0);
    let m = lightcraft_gpu::memory();
    assert_eq!(m.pooled, 0);
    assert!(m.allocated < before, "trimming frees the pooled buffers: {} → {}", before, m.allocated);
}

//! Ember's MCP server.
//!
//! [Model Context Protocol](https://modelcontextprotocol.io) over stdio: newline-delimited
//! JSON-RPC 2.0, hand-written (no async runtime). The server exposes Ember as MCP tools and
//! resources and forwards everything to a [`Backend`]:
//!
//! - [`Remote`] talks to a running desktop app through its loopback JSON-lines control channel
//!   (`lightcraft --control 7980`): one `{"id","method","params"}` line in, one
//!   `{"id","ok","result"|"error"}` line out (see `docs/control-protocol.md`).
//! - [`Headless`] hosts an in-process [`lightcraft_engine::Session`] and answers the same
//!   control-channel method names itself (rendering with the engine's pipeline and encoding with
//!   `lightcraft-codecs`), so agents can develop photos and look at the result without a window.
//!
//! Entry points: [`Server::serve`] (stdio loop) and [`Server::handle_line`] (one message).
#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

mod backend;
mod base64;
mod headless;
mod server;
mod tools;

pub use backend::{Backend, ProgressHook, Remote};
pub use base64::{base64_decode, base64_encode};
pub use headless::{Headless, encode_image, expand_paths, write_image};
pub use server::{PROTOCOL_VERSION, Server};
pub use tools::{COMMAND_TOOL_PREFIX, ToolResult, call_tool, command_tool_name, helper_tools, tool_definitions};

/// Default control-channel address of the desktop app (`lightcraft --control 7980`).
pub const DEFAULT_ADDR: &str = "127.0.0.1:7980";

#[cfg(test)]
mod tests;

//! JSON-RPC 2.0 framing and the MCP lifecycle / tools / resources methods.

use std::io::{BufRead, Write};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};

#[path = "progress.rs"]
mod progress;

use serde_json::{Value, json};

use crate::backend::Backend;
use crate::tools::{ToolResult, call_tool, check_args, doc_inspect, tool_definitions};

/// The MCP revision we implement.
pub const PROTOCOL_VERSION: &str = "2025-06-18";
/// Revisions we can speak; anything else negotiates down to [`PROTOCOL_VERSION`].
const SUPPORTED_VERSIONS: &[&str] = &[PROTOCOL_VERSION, "2025-03-26", "2024-11-05"];

const PARSE_ERROR: i64 = -32700;
const INVALID_REQUEST: i64 = -32600;
const METHOD_NOT_FOUND: i64 = -32601;
const INVALID_PARAMS: i64 = -32602;
const INTERNAL_ERROR: i64 = -32603;
const RESOURCE_NOT_FOUND: i64 = -32002;

const INSTRUCTIONS: &str = "Ember is a non-destructive photo library and raw developer. \
Photos have integer ids; most editing acts on the *active* photo (`set_develop`, `crop` and `export` with an explicit photo id end the current edit interaction, replace the selection with that one photo and make it active; `get_develop` and `render_photo` do not change the selection). \
Typical loop: query_photos → select_photos (or pass id) → list_controls → set_develop {values: {\"light.exposure\": 0.5}} → \
render_preview to look at the result → export. Positions (crop rects, mask points, brush strokes) are normalized image \
coordinates 0..1 with the origin at the top-left. Every action is a command: command_list shows ids and parameter \
docs; command_run {id, params} runs any of them; command_batch runs steps in order. Inspect with doc_inspect. Edits are undoable (undo / redo).";

/// Resource URIs.
pub const DOCUMENT_URI: &str = "lightcraft://document";
pub const COMMANDS_URI: &str = "lightcraft://commands";
pub const LIBRARY_URI: &str = "lightcraft://library";
pub const PHOTOS_URI: &str = "lightcraft://photos";
pub const PHOTO_URI: &str = "lightcraft://photo/active";
pub const DEVELOP_URI: &str = "lightcraft://develop/active";
pub const CONTROLS_URI: &str = "lightcraft://controls";

/// An MCP server bound to one backend.
pub struct Server {
    backend: Box<dyn Backend>,
    initialized: bool,
    command_tools: bool,
    wire: Option<progress::Wire>,
    current: Option<(Value, Option<Value>)>,
    suppress: Arc<AtomicBool>,
}

fn response(id: Value, result: Value) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "result": result})
}

fn error(id: Value, code: i64, message: impl Into<String>) -> Value {
    json!({"jsonrpc": "2.0", "id": id, "error": {"code": code, "message": message.into()}})
}

fn resource(uri: &str, name: &str, title: &str, description: &str) -> Value {
    json!({"uri": uri, "name": name, "title": title, "description": description, "mimeType": "application/json"})
}

impl Server {
    pub fn new(backend: Box<dyn Backend>) -> Self {
        Self { backend, initialized: false, command_tools: true, wire: None, current: None, suppress: Arc::new(AtomicBool::new(false)) }
    }

    /// Whether `tools/list` includes one `cmd_*` tool per registered command (default true).
    /// Off, every command stays reachable through `run_command`.
    pub fn with_command_tools(mut self, on: bool) -> Self {
        self.command_tools = on;
        self
    }

    pub fn backend(&mut self) -> &mut dyn Backend {
        self.backend.as_mut()
    }

    /// Whether the client has sent `notifications/initialized`.
    pub fn is_initialized(&self) -> bool {
        self.initialized
    }

    /// Serve newline-delimited JSON-RPC until `input` closes. Logs go to stderr only (stdout is
    /// the protocol stream).
    pub fn serve(&mut self, input: impl BufRead + Send, output: impl Write + Send) -> std::io::Result<()> {
        self.serve_wire(input, output)
    }

    /// Handle one line; returns the reply line (None for notifications and blank lines).
    pub fn handle_line(&mut self, line: &str) -> Option<String> {
        let line = line.trim();
        if line.is_empty() {
            return None;
        }
        let reply = match serde_json::from_str::<Value>(line) {
            Ok(Value::Array(batch)) => {
                // Batches were removed in 2025-06-18; still answer older clients sensibly.
                if batch.is_empty() {
                    Some(error(Value::Null, INVALID_REQUEST, "empty batch"))
                } else {
                    let replies: Vec<Value> = batch.into_iter().filter_map(|m| self.handle(m)).collect();
                    (!replies.is_empty()).then_some(Value::Array(replies))
                }
            }
            Ok(msg) => self.handle(msg),
            Err(e) => Some(error(Value::Null, PARSE_ERROR, format!("parse error: {e}"))),
        };
        reply.map(|r| r.to_string())
    }

    /// Handle one JSON-RPC message; `None` for notifications and responses.
    pub fn handle(&mut self, msg: Value) -> Option<Value> {
        let Value::Object(o) = &msg else { return Some(error(Value::Null, INVALID_REQUEST, "message must be an object")) };
        let id = o.get("id").cloned();
        let Some(method) = o.get("method").and_then(Value::as_str) else {
            // A response to a server→client request (we send none) — ignore; anything else is invalid.
            if o.contains_key("result") || o.contains_key("error") {
                return None;
            }
            return Some(error(id.filter(|i| i.is_string() || i.is_number()).unwrap_or(Value::Null), INVALID_REQUEST, "missing `method`"));
        };
        let params = o.get("params").cloned().unwrap_or(Value::Null);
        let Some(id) = id else {
            self.notification(method, &params);
            return None;
        };
        if !(id.is_string() || id.is_number()) {
            return Some(error(Value::Null, INVALID_REQUEST, "`id` must be a string or number"));
        }
        if !(params.is_object() || params.is_null()) {
            return Some(error(id, INVALID_PARAMS, "`params` must be an object"));
        }
        let token = params.get("_meta").and_then(|m| m.get("progressToken")).filter(|t| t.is_string() || t.is_number()).cloned();
        self.current = Some((id.clone(), token));
        self.suppress.store(false, Ordering::Relaxed);
        let result = self.request(method, &params);
        self.current = None;
        if self.suppress.swap(false, Ordering::Relaxed) {
            return None;
        }
        Some(match result {
            Ok(mut r) => {
                modern_result_fields(method, &params, &mut r);
                response(id, r)
            }
            Err((code, m)) => error(id, code, m),
        })
    }

    fn notification(&mut self, method: &str, _params: &Value) {
        match method {
            "notifications/initialized" => self.initialized = true,
            "notifications/cancelled" | "notifications/progress" | "notifications/roots/list_changed" => {}
            other => log::debug!("ignoring notification {other}"),
        }
    }

    fn request(&mut self, method: &str, params: &Value) -> Result<Value, (i64, String)> {
        match method {
            "initialize" => {
                let asked = params.get("protocolVersion").and_then(Value::as_str).unwrap_or(PROTOCOL_VERSION);
                let version = if SUPPORTED_VERSIONS.contains(&asked) { asked } else { PROTOCOL_VERSION };
                Ok(json!({
                    "protocolVersion": version,
                    "capabilities": {"tools": {"listChanged": false}, "resources": {"subscribe": false, "listChanged": false}},
                    "serverInfo": {"name": "lightcraft", "title": "Ember", "version": env!("CARGO_PKG_VERSION")},
                    "instructions": format!("{INSTRUCTIONS} Backend: {}.", self.backend.describe()),
                }))
            }
            "ping" => Ok(json!({})),
            "tools/list" => {
                let command_tools = self.command_tools;
                let tools = self.guarded(|b| tool_definitions(b, command_tools)).map_err(|e| (INTERNAL_ERROR, e))?;
                Ok(json!({"tools": tools}))
            }
            "tools/call" => {
                let name = params.get("name").and_then(Value::as_str).ok_or((INVALID_PARAMS, "missing tool `name`".to_string()))?;
                let args = params.get("arguments").cloned().unwrap_or(Value::Null);
                check_args(name, &args).map_err(|e| (INVALID_PARAMS, e))?;
                let long = matches!(name, "export" | "cmd_app_export")
                    || (name == "command_run" && args["id"] == "app.export")
                    || (name == "run_command" && args["command"] == "app.export");
                let hook = if long && !self.backend.has_ui() { self.progress_hook() } else { None };
                let result = self.guarded(|b| {
                    b.set_progress(hook);
                    call_tool(b, name, &args)
                });
                let clear = self.guarded(|b| b.set_progress(None));
                let result = match (result, clear) {
                    (Ok(result), Ok(())) => result,
                    (Err(error), _) | (_, Err(error)) => ToolResult::error(error),
                };
                Ok(result.to_value())
            }
            "resources/list" => Ok(json!({"resources": [
                resource(DOCUMENT_URI, "document", "Library document", "Library state and counts (same as doc_inspect)"),
                resource(COMMANDS_URI, "commands", "Command catalog", "Every command (same as command_list)"),
                resource(LIBRARY_URI, "library", "Library state", "Current source, filter, sort, selection, active photo/mask and undo/redo labels (library.state)"),
                resource(PHOTOS_URI, "photos", "Photos in view", "The photos in the current view with ids, ratings, flags and metadata (catalog.query)"),
                resource(PHOTO_URI, "active-photo", "Active photo", "Everything about the active photo: file, metadata, develop settings, albums, history (photo.inspect)"),
                resource(DEVELOP_URI, "develop", "Develop settings", "The active photo's full develop settings JSON (develop.get)"),
                resource(CONTROLS_URI, "controls", "Develop controls", "Every develop slider with id, range, default and current value (develop.controls)"),
            ]})),
            "resources/templates/list" => Ok(json!({"resourceTemplates": []})),
            "resources/read" => {
                let uri = params.get("uri").and_then(Value::as_str).ok_or((INVALID_PARAMS, "missing `uri`".to_string()))?;
                let cmd = match uri {
                    DOCUMENT_URI | COMMANDS_URI => "",
                    LIBRARY_URI => "library.state",
                    PHOTOS_URI => "catalog.query",
                    PHOTO_URI => "photo.inspect",
                    DEVELOP_URI => "develop.get",
                    CONTROLS_URI => "develop.controls",
                    _ => return Err((RESOURCE_NOT_FOUND, format!("resource not found: {uri}"))),
                };
                let v = self
                    .guarded(|b| match uri {
                        DOCUMENT_URI => doc_inspect(b),
                        COMMANDS_URI => b.call("engine.commands", json!({})),
                        _ => b.call("engine.execute", json!({"command": cmd, "params": {}})),
                    })
                    .and_then(|v| v)
                    .map_err(|e| (INTERNAL_ERROR, e))?;
                Ok(json!({"contents": [{"uri": uri, "mimeType": "application/json", "text": serde_json::to_string_pretty(&v).unwrap_or_default()}]}))
            }
            other => Err((METHOD_NOT_FOUND, format!("method not found: {other}"))),
        }
    }
}

impl Server {
    /// Escaped backend panics become errors; subsequent requests can keep using the session.
    fn guarded<T>(&mut self, f: impl FnOnce(&mut dyn Backend) -> T) -> Result<T, String> {
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| f(self.backend.as_mut()))).map_err(|p| {
            let message =
                p.downcast_ref::<&str>().map(|s| s.to_string()).or_else(|| p.downcast_ref::<String>().cloned()).unwrap_or_else(|| "panic".into());
            format!("internal error: {message}")
        })
    }
}

/// Per-request protocol metadata leaves initialize-based clients' result shapes unchanged.
fn modern_result_fields(method: &str, params: &Value, result: &mut Value) {
    let modern = params.pointer("/_meta/io.modelcontextprotocol~1protocolVersion").and_then(Value::as_str).is_some_and(|v| v >= "2026-07-28");
    let ttl = match method {
        "tools/list" | "resources/list" | "resources/templates/list" => Some(600_000),
        "resources/read" => Some(0),
        "tools/call" => None,
        _ => return,
    };
    let Some(obj) = result.as_object_mut().filter(|_| modern) else {
        return;
    };
    obj.insert("resultType".into(), json!("complete"));
    if let Some(ttl) = ttl {
        obj.insert("ttlMs".into(), json!(ttl));
        obj.insert("cacheScope".into(), json!("private"));
    }
}

//! Frame alignment for HDR brackets (handheld, small motion): features on exposure-normalised,
//! gamma-encoded luminance at ≤ 1200 px, matched to the reference frame, then a RANSAC homography
//! (falling back to similarity, then translation, then identity when the scene gives too little).

use lightcraft_geom::{Homography, Point};
use lightcraft_raster::resample::{Filter, fit};
use lightcraft_raster::{Plane, Rgb32f};
use rayon::prelude::*;

use crate::features::{self, Features};
use crate::ransac::{self, Model};

/// Long edge of the images features are detected on.
pub const WORK_EDGE: usize = 1200;

/// A grey, perceptually encoded work image: `(luminance · gain)^(1/2.2)`, clamped to 0..1, and
/// the scale from full-resolution pixels to work pixels.
pub fn work_image(img: &Rgb32f, gain: f32, max_edge: usize) -> (Plane, f64) {
    let small = if img.width.max(img.height) > max_edge { fit(img, max_edge, max_edge, Filter::Box) } else { img.clone() };
    let scale = small.width as f64 / img.width as f64;
    let p = small.map(|c| {
        let y = (0.25 * c[0] + 0.6 * c[1] + 0.15 * c[2]) * gain;
        y.clamp(0.0, 1.0).powf(1.0 / 2.2)
    });
    (p, scale)
}

/// Median luminance of the (unsaturated, non-black) pixels: a brightness estimate for frames
/// without EXIF.
pub fn median_luma(img: &Rgb32f, clip: f32) -> f32 {
    let step = (img.data.len() / 100_000).max(1);
    let mut v: Vec<f32> =
        img.data.iter().step_by(step).filter(|p| p[0].max(p[1]).max(p[2]) < clip * 0.98).map(|c| 0.25 * c[0] + 0.6 * c[1] + 0.15 * c[2]).collect();
    if v.is_empty() {
        return clip;
    }
    v.sort_by(|a, b| a.total_cmp(b));
    v[v.len() / 2].max(1e-6)
}

#[derive(Clone, Debug)]
pub struct Alignment {
    /// Maps reference pixel coordinates to this frame's coordinates (full resolution).
    pub h: Homography,
    pub model: &'static str,
    pub inliers: usize,
    pub rms: f64,
}

impl Alignment {
    pub fn identity() -> Alignment {
        Alignment { h: Homography::IDENTITY, model: "identity", inliers: 0, rms: 0.0 }
    }
}

/// Conjugate a work-resolution homography to full resolution: S⁻¹ · H · S with S = diag(s, s, 1).
pub fn scale_homography(h: &Homography, s: f64) -> Homography {
    let m = h.0;
    Homography([m[0], m[1], m[2] / s, m[3], m[4], m[5] / s, m[6] * s, m[7] * s, m[8]])
}

/// Whether `h` is a plausible handheld motion for a `w × h` frame: corners move less than
/// `max_frac` of the diagonal and the area changes by < 20 %.
pub fn plausible(h: &Homography, w: f64, ht: f64, max_frac: f64) -> bool {
    let diag = (w * w + ht * ht).sqrt();
    let corners = [Point::new(0.0, 0.0), Point::new(w, 0.0), Point::new(w, ht), Point::new(0.0, ht)];
    let moved: Vec<Point> = corners.iter().map(|&c| h.apply(c)).collect();
    if corners.iter().zip(&moved).any(|(a, b)| a.dist(*b) > max_frac * diag || !b.x.is_finite() || !b.y.is_finite()) {
        return false;
    }
    let area = |p: &[Point]| {
        let mut s = 0.0;
        for i in 0..p.len() {
            let (a, b) = (p[i], p[(i + 1) % p.len()]);
            s += a.x * b.y - b.x * a.y;
        }
        s.abs() / 2.0
    };
    let r = area(&moved) / (w * ht);
    (0.8..1.25).contains(&r)
}

/// Align `frame` to `reference` (both as work images with features already detected).
pub fn align_pair(ref_feat: &Features, feat: &Features, scale: f64, full_w: usize, full_h: usize, seed: u64) -> Alignment {
    let m = features::match_features(ref_feat, feat, 0.8);
    let a: Vec<Point> = m.iter().map(|(i, _)| Point::new(ref_feat.points[*i].x as f64, ref_feat.points[*i].y as f64)).collect();
    let b: Vec<Point> = m.iter().map(|(_, j)| Point::new(feat.points[*j].x as f64, feat.points[*j].y as f64)).collect();
    let (ww, wh) = (full_w as f64 * scale, full_h as f64 * scale);
    // Fit every model; keep the simplest one that explains (almost) as many matches as the most
    // general one — extra degrees of freedom fitted to clustered points extrapolate badly.
    let mut fits: Vec<(&'static str, ransac::Fit)> = Vec::new();
    for (model, name, min) in [(Model::Translation, "translation", 5), (Model::Similarity, "similarity", 8), (Model::Homography, "homography", 16)] {
        if let Some(f) = ransac::ransac(model, &a, &b, 1.5, min, seed)
            && plausible(&f.h, ww, wh, 0.12)
        {
            fits.push((name, f));
        }
    }
    let Some(most) = fits.iter().map(|(_, f)| f.inliers.len()).max() else { return Alignment::identity() };
    // the fit with `most` inliers always qualifies
    let Some((name, f)) = fits.into_iter().find(|(_, f)| f.inliers.len() as f64 >= most as f64 * 0.97) else { return Alignment::identity() };
    Alignment { h: scale_homography(&f.h, scale), model: name, inliers: f.inliers.len(), rms: f.rms / scale }
}

/// Resample `img` into the reference geometry: `out(p) = img(h(p))`. Returns the warped image and
/// a validity mask (false where `h(p)` falls outside `img`).
pub fn warp(img: &Rgb32f, h: &Homography) -> (Rgb32f, Vec<bool>) {
    let (w, ht) = (img.width, img.height);
    if *h == Homography::IDENTITY {
        return (img.clone(), vec![true; w * ht]);
    }
    let mut out = Rgb32f::new(w, ht);
    let mut valid = vec![false; w * ht];
    out.data.par_chunks_mut(w).zip(valid.par_chunks_mut(w)).enumerate().for_each(|(y, (row, vrow))| {
        for x in 0..w {
            let p = h.apply(Point::new(x as f64 + 0.5, y as f64 + 0.5));
            let (sx, sy) = (p.x as f32, p.y as f32);
            if sx >= 0.0 && sy >= 0.0 && sx <= w as f32 && sy <= ht as f32 {
                row[x] = img.sample_bilinear(sx, sy);
                vrow[x] = true;
            }
        }
    });
    (out, valid)
}

