                + (u * 0.023 + v * 0.031).sin() * 0.7
                + ((u * 0.011).floor() as i32 + (v * 0.013).floor() as i32).rem_euclid(2) as f32 * 0.6)
                * 0.25
                + 0.5;
            a.clamp(0.0, 1.0)
        })
    }

    #[test]
    fn shifted_images_match_with_the_shift() {
        let a = pattern(400, 300, 0.0, 0.0);
        let b = pattern(400, 300, 7.0, -4.0);
        let fa = detect(&a, 300);
        let fb = detect(&b, 300);
        assert!(fa.len() > 50, "{} features", fa.len());
        let m = match_features(&fa, &fb, 0.8);
        assert!(m.len() > 20, "{} matches", m.len());
        let good = m
            .iter()
            .filter(|(i, j)| {
                let (p, q) = (fa.points[*i], fb.points[*j]);
                ((q.x - p.x - 7.0).powi(2) + (q.y - p.y + 4.0).powi(2)).sqrt() < 1.5
            })
            .count();
        assert!(good as f32 > m.len() as f32 * 0.8, "{good}/{}", m.len());
    }
}

//! Panorama finishing: boundary warp, auto crop, fill edges.
//!
//! - **Boundary warp** (0–100): a separable stretch that maps, per column, the smoothed top and
//!   bottom edges of the valid area to the canvas edges, then per row the left and right edges;
//!   `amount` blends between the identity and that stretch. (A simple, documented alternative to
//!   content-preserving mesh warps.)
//! - **Auto crop**: the largest axis-aligned rectangle of fully valid pixels (maximal rectangle in a
//!   binary matrix via a per-row histogram and a monotone stack, O(w·h)).
//! - **Fill edges**: transparent areas are filled by push–pull diffusion of the surrounding pixels
//!   in log space (no patch synthesis).

use lightcraft_raster::{Plane, Rgb32f};
use rayon::prelude::*;

use super::blend::{Buf, push_pull};

fn edges(alpha: &Plane, vertical: bool) -> Option<(Vec<f64>, Vec<f64>)> {
    let (w, h) = (alpha.width, alpha.height);
    let (n, len) = if vertical { (w, h) } else { (h, w) };
    let at = |i: usize, k: usize| if vertical { alpha.get(i, k) } else { alpha.get(k, i) };
    let mut lo = vec![f64::NAN; n];
    let mut hi = vec![f64::NAN; n];
    for i in 0..n {
        if let Some(a) = (0..len).find(|&k| at(i, k) >= 0.5) {
            let b = (0..len).rev().find(|&k| at(i, k) >= 0.5).unwrap_or(a);
            lo[i] = a as f64;
            hi[i] = b as f64 + 1.0;
        }
    }
    let known: Vec<usize> = (0..n).filter(|&i| lo[i].is_finite()).collect();
    if known.len() < 2 {
        return None;
    }
    // fill gaps by linear interpolation / nearest at the ends
    for i in 0..n {
        if lo[i].is_finite() {
            continue;
        }
        let p = known.iter().rev().find(|&&k| k < i).copied();
        let q = known.iter().find(|&&k| k > i).copied();
        let (a, b) = match (p, q) {
            (Some(p), Some(q)) => {
                let t = (i - p) as f64 / (q - p) as f64;
                (lo[p] + (lo[q] - lo[p]) * t, hi[p] + (hi[q] - hi[p]) * t)
            }
            (Some(p), None) => (lo[p], hi[p]),
            (None, Some(q)) => (lo[q], hi[q]),
            _ => (0.0, len as f64),
        };
        lo[i] = a;
        hi[i] = b;
    }
    // smooth (box, radius n/40) so the stretch follows the overall shape, not every jag
    let r = (n / 40).max(1) as isize;
    let smooth = |v: &[f64]| -> Vec<f64> {
        (0..n as isize)
            .map(|i| {
                let (a, b) = ((i - r).max(0) as usize, ((i + r) as usize).min(n - 1));
                v[a..=b].iter().sum::<f64>() / (b - a + 1) as f64
            })
            .collect()
    };
    Some((smooth(&lo), smooth(&hi)))
}

fn stretch(img: &Rgb32f, alpha: &Plane, amount: f64, vertical: bool) -> (Rgb32f, Plane) {
    let Some((lo, hi)) = edges(alpha, vertical) else { return (img.clone(), alpha.clone()) };
    let (w, h) = (img.width, img.height);
    let len = if vertical { h } else { w } as f64;
    let mut out = Rgb32f::new(w, h);
    let mut oa = Plane::new(w, h);
    out.data.par_chunks_mut(w).zip(oa.data.par_chunks_mut(w)).enumerate().for_each(|(y, (row, arow))| {
        for x in 0..w {
            let (i, k) = if vertical { (x, y) } else { (y, x) };
            let t = (k as f64 + 0.5) / len;
            let src = lo[i] + t * (hi[i] - lo[i]);
            let s = (1.0 - amount) * (k as f64 + 0.5) + amount * src;
            let (sx, sy) = if vertical { (x as f32 + 0.5, s as f32) } else { (s as f32, y as f32 + 0.5) };
            row[x] = img.sample_bilinear(sx, sy);
            arow[x] = crate::features::bilinear(alpha, sx, sy);
        }
    });
    (out, oa)
}

/// Boundary warp by `amount` (0..1).
pub fn boundary_warp(img: &Rgb32f, alpha: &Plane, amount: f64) -> (Rgb32f, Plane) {
    if amount <= 0.0 {
        return (img.clone(), alpha.clone());
    }
    let amount = amount.min(1.0);
    let (i1, a1) = stretch(img, alpha, amount, true);
    stretch(&i1, &a1, amount, false)
}

/// Largest axis-aligned rectangle where `alpha ≥ 0.999`: (x, y, w, h) in pixels.
pub fn auto_crop(alpha: &Plane) -> Option<(usize, usize, usize, usize)> {
    let (w, h) = (alpha.width, alpha.height);
    if w == 0 || h == 0 {
        return None;
    }
    // work on a ≤ 1500 px grid with conservative (min) pooling
    let f = w.max(h).div_ceil(1500).max(1);
    let (gw, gh) = (w.div_ceil(f), h.div_ceil(f));
    let ok = |gx: usize, gy: usize| -> bool {
        for y in gy * f..((gy + 1) * f).min(h) {
            for x in gx * f..((gx + 1) * f).min(w) {
                if alpha.get(x, y) < 0.999 {
                    return false;
                }
            }
        }
        true
    };
    let grid: Vec<bool> = (0..gh).into_par_iter().flat_map_iter(|gy| (0..gw).map(move |gx| (gx, gy))).map(|(gx, gy)| ok(gx, gy)).collect();
    let mut heights = vec![0usize; gw];
    let mut best = (0usize, 0, 0, 0, 0); // area, x, y, w, h
    for gy in 0..gh {
        for gx in 0..gw {
            heights[gx] = if grid[gy * gw + gx] { heights[gx] + 1 } else { 0 };
        }
        let mut stack: Vec<usize> = Vec::new();
        for i in 0..=gw {
            let cur = if i < gw { heights[i] } else { 0 };
            while let Some(&top) = stack.last() {
                if heights[top] <= cur {
                    break;
                }
                stack.pop();
                let hgt = heights[top];
                let left = stack.last().map_or(0, |&s| s + 1);
                let width = i - left;
                let area = hgt * width;
                if area > best.0 {
                    best = (area, left, gy + 1 - hgt, width, hgt);
                }
            }
            stack.push(i);
        }
    }
    if best.0 == 0 {
        return None;
    }
    let (x, y) = (best.1 * f, best.2 * f);
    Some((x, y, (best.3 * f).min(w - x), (best.4 * f).min(h - y)))
}

/// Fill transparent pixels (alpha < 1) from their surroundings; returns the image with alpha 1.
pub fn fill_edges(img: &Rgb32f, alpha: &Plane) -> Rgb32f {
    let (w, h) = (img.width, img.height);
    let mut b = Buf::new(w, h, 3);
    for (i, p) in img.data.iter().enumerate() {
        for c in 0..3 {
            b.data[i * 3 + c] = (p[c].max(1e-6)).ln();
        }
    }
    let wgt: Vec<f32> = alpha.data.iter().map(|a| if *a >= 0.999 { 1.0 } else { 0.0 }).collect();
    push_pull(&mut b, &wgt);
    let mut out = img.clone();
    for (i, p) in out.data.iter_mut().enumerate() {
        let a = alpha.data[i].clamp(0.0, 1.0);
        if a < 0.999 {
            let f = [0, 1, 2].map(|c| b.data[i * 3 + c].exp());
            // the warped/blended edge pixels are premultiplied-like: un-premultiply then mix
            let v = if a > 1e-3 { p.map(|v| v / a) } else { [0.0; 3] };
            *p = [0, 1, 2].map(|c| v[c] * a + f[c] * (1.0 - a));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn crop_finds_the_largest_rectangle() {
        let mut a = Plane::new(100, 60);
        for y in 10..50 {
            for x in 5..90 {
                a.set(x, y, 1.0);
            }
        }
        for y in 0..60 {
            a.set(40, y, 1.0); // a thin spike doesn't matter
        }
        assert_eq!(auto_crop(&a), Some((5, 10, 85, 40)));
    }

    #[test]
    fn warp_fills_a_curved_boundary() {
        let (w, h) = (200, 100);
        let mut a = Plane::new(w, h);
        let img = Rgb32f::from_fn(w, h, |x, _| [(x + 1) as f32 / w as f32; 3]);
        for x in 0..w {
            let dip = (10.0 * (1.0 - ((x as f32 - 100.0) / 100.0).powi(2))) as usize;
            for y in dip..h - dip {
                a.set(x, y, 1.0);
            }
        }
        let before = a.data.iter().filter(|v| **v >= 0.5).count();
        let (_, a2) = boundary_warp(&img, &a, 1.0);
        let after = a2.data.iter().filter(|v| **v >= 0.5).count();
        assert!(after as f64 > 0.97 * (w * h) as f64 && after > before, "{before} → {after}");
        let (_, a0) = boundary_warp(&img, &a, 0.0);
        assert_eq!(a0, a);
        let filled = fill_edges(&img, &a);
        assert!(filled.data.iter().all(|p| p[0] > 0.0));
    }
}

//! Robust 2-D motion models: normalised DLT homographies (Hartley & Zisserman, "Multiple View
//! Geometry", §4.4) and RANSAC (Fischler & Bolles 1981) with the adaptive iteration count.
//! Deterministic: the sampler is a fixed-seed xorshift, so results are reproducible.

use lightcraft_geom::{Homography, Point};

use crate::linalg::sym_eigen;

/// The kind of motion to fit.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Model {
    Translation,
    /// Rotation + uniform scale + translation (4 dof).
    Similarity,
    Homography,
}

impl Model {
    fn min_samples(self) -> usize {
        match self {
            Model::Translation => 1,
            Model::Similarity => 2,
            Model::Homography => 4,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Fit {
    /// Maps points of the first set to the second.
    pub h: Homography,
    pub inliers: Vec<usize>,
    /// RMS transfer error of the inliers (pixels).
    pub rms: f64,
}

/// Small deterministic PRNG (xorshift64*).
pub struct Rng(u64);

impl Rng {
    pub fn new(seed: u64) -> Rng {
        Rng(seed.max(1))
    }
    pub fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }
    pub fn below(&mut self, n: usize) -> usize {
        (self.next_u64() % n.max(1) as u64) as usize
    }
    /// Uniform in [0, 1).
    pub fn unit(&mut self) -> f64 {
        (self.next_u64() >> 11) as f64 / (1u64 << 53) as f64
    }
}

/// Least-squares fit of `model` to all pairs (`a[i]` → `b[i]`).
pub fn fit_model(model: Model, a: &[Point], b: &[Point]) -> Option<Homography> {
    let n = a.len().min(b.len());
    if n < model.min_samples() {
        return None;
    }
    match model {
        Model::Translation => {
            let (mut dx, mut dy) = (0.0, 0.0);
            for i in 0..n {
                dx += b[i].x - a[i].x;
                dy += b[i].y - a[i].y;
            }
            Some(Homography([1.0, 0.0, dx / n as f64, 0.0, 1.0, dy / n as f64, 0.0, 0.0, 1.0]))
        }
        Model::Similarity => {
            // closed form (Umeyama without reflection): b ≈ s R a + t
            let ca = centroid(&a[..n]);
            let cb = centroid(&b[..n]);
            let (mut sxx, mut sxy, mut var) = (0.0, 0.0, 0.0);
            for i in 0..n {
                let (ax, ay) = (a[i].x - ca.x, a[i].y - ca.y);
                let (bx, by) = (b[i].x - cb.x, b[i].y - cb.y);
                sxx += ax * bx + ay * by;
                sxy += ax * by - ay * bx;
                var += ax * ax + ay * ay;
            }
            if var < 1e-12 {
                return None;
            }
            let (c, s) = (sxx / var, sxy / var);
            let tx = cb.x - (c * ca.x - s * ca.y);
            let ty = cb.y - (s * ca.x + c * ca.y);
            Some(Homography([c, -s, tx, s, c, ty, 0.0, 0.0, 1.0]))
        }
        Model::Homography => dlt(&a[..n], &b[..n]),
    }
}

fn centroid(p: &[Point]) -> Point {
    let n = p.len().max(1) as f64;
    Point::new(p.iter().map(|q| q.x).sum::<f64>() / n, p.iter().map(|q| q.y).sum::<f64>() / n)
}

/// Hartley normalisation: translate to the centroid, scale to mean distance √2.
fn normaliser(p: &[Point]) -> [f64; 3] {
    let c = centroid(p);
    let md = p.iter().map(|q| ((q.x - c.x).powi(2) + (q.y - c.y).powi(2)).sqrt()).sum::<f64>() / p.len().max(1) as f64;
    let s = if md > 1e-12 { std::f64::consts::SQRT_2 / md } else { 1.0 };
    [s, -s * c.x, -s * c.y]
}

/// Normalised direct linear transform (≥ 4 points).
pub fn dlt(a: &[Point], b: &[Point]) -> Option<Homography> {
    let n = a.len();
    if n < 4 {
        return None;
    }
    let ta = normaliser(a);
    let tb = normaliser(b);
    let mut ata = [0.0f64; 81];
    for i in 0..n {
        let (x, y) = (a[i].x * ta[0] + ta[1], a[i].y * ta[0] + ta[2]);
        let (u, v) = (b[i].x * tb[0] + tb[1], b[i].y * tb[0] + tb[2]);
        let r1 = [-x, -y, -1.0, 0.0, 0.0, 0.0, u * x, u * y, u];
        let r2 = [0.0, 0.0, 0.0, -x, -y, -1.0, v * x, v * y, v];
        for r in [r1, r2] {
            for p in 0..9 {
                if r[p] == 0.0 {
                    continue;
                }
                for q in 0..9 {
                    ata[p * 9 + q] += r[p] * r[q];
                }
            }
        }
    }
    let (_, vecs) = sym_eigen(&ata, 9);
    let h = &vecs[0];
    let hn = Homography([h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7], h[8]]);
    // denormalise: H = Tb⁻¹ · Hn · Ta
    let ta_m = Homography([ta[0], 0.0, ta[1], 0.0, ta[0], ta[2], 0.0, 0.0, 1.0]);
    let tb_inv = Homography([1.0 / tb[0], 0.0, -tb[1] / tb[0], 0.0, 1.0 / tb[0], -tb[2] / tb[0], 0.0, 0.0, 1.0]);
    let h = tb_inv.mul(&hn).mul(&ta_m);
    let s = h.0[8];
    if s.abs() < 1e-14 || h.0.iter().any(|v| !v.is_finite()) {
        return None;
    }
    Some(Homography(h.0.map(|v| v / s)))
}

pub fn transfer_error2(h: &Homography, a: Point, b: Point) -> f64 {
    let p = h.apply(a);
    (p.x - b.x).powi(2) + (p.y - b.y).powi(2)
}

/// RANSAC fit of `model` mapping `a` → `b`, inlier threshold `thresh` pixels. Refits on the
/// inliers (twice) and returns `None` when fewer than `min_inliers` agree.
pub fn ransac(model: Model, a: &[Point], b: &[Point], thresh: f64, min_inliers: usize, seed: u64) -> Option<Fit> {
    let n = a.len().min(b.len());
    let k = model.min_samples();
    if n < k.max(min_inliers) {
        return None;
    }
    let t2 = thresh * thresh;
    let mut rng = Rng::new(seed ^ 0x9e37_79b9_7f4a_7c15);
    let mut best: Vec<usize> = Vec::new();
    let mut iters = 2000usize;
    let mut it = 0;
    let mut sa = Vec::with_capacity(k);
    let mut sb = Vec::with_capacity(k);
    while it < iters {
        it += 1;
        sa.clear();
        sb.clear();
        let mut idx = [usize::MAX; 4];
        let mut ok = true;
        for s in 0..k {
            let mut tries = 0;
            let i = loop {
                let i = rng.below(n);
                if !idx[..s].contains(&i) {
                    break i;
                }
                tries += 1;
                if tries > 20 {
                    ok = false;
                    break i;
                }
            };
            idx[s] = i;
            sa.push(a[i]);
            sb.push(b[i]);
        }
        if !ok {
            continue;
        }
        let h = match model {
            Model::Homography => {
                let src = [sa[0], sa[1], sa[2], sa[3]];
                let dst = [sb[0], sb[1], sb[2], sb[3]];
                if degenerate(&src) || degenerate(&dst) {
                    continue;
                }
                match Homography::from_quads(&src, &dst) {
                    Some(h) => h,
                    None => continue,
                }
            }
            _ => match fit_model(model, &sa, &sb) {
                Some(h) => h,
                None => continue,
            },
        };
        let inl: Vec<usize> = (0..n).filter(|&i| transfer_error2(&h, a[i], b[i]) < t2).collect();
        if inl.len() > best.len() {
            best = inl;
            let w = best.len() as f64 / n as f64;
            let p_fail = 1.0 - w.powi(k as i32);
            if p_fail <= 1e-12 {
                iters = it;
            } else {
                let need = ((1e-3f64).ln() / p_fail.ln()).ceil();
                iters = iters.min(need.max(16.0) as usize);
            }
        }
    }
    if best.len() < min_inliers.max(k) {
        return None;
    }
    let mut h = None;
    for _ in 0..3 {
        let ia: Vec<Point> = best.iter().map(|&i| a[i]).collect();
        let ib: Vec<Point> = best.iter().map(|&i| b[i]).collect();
        let Some(hh) = fit_model(model, &ia, &ib) else { break };
        let inl: Vec<usize> = (0..n).filter(|&i| transfer_error2(&hh, a[i], b[i]) < t2).collect();
        h = Some(hh);
        if inl.len() < best.len() || inl == best {
            break;
        }
        best = inl;
    }
    let h = h?;
    if best.len() < min_inliers.max(k) {
        return None;
    }
    let rms = (best.iter().map(|&i| transfer_error2(&h, a[i], b[i])).sum::<f64>() / best.len() as f64).sqrt();
    Some(Fit { h, inliers: best, rms })
}

/// Three (nearly) collinear points among the four.
fn degenerate(p: &[Point; 4]) -> bool {
    for (i, j, k) in [(0, 1, 2), (0, 1, 3), (0, 2, 3), (1, 2, 3)] {
        let area = ((p[j].x - p[i].x) * (p[k].y - p[i].y) - (p[j].y - p[i].y) * (p[k].x - p[i].x)).abs();
        let scale = p[i].dist(p[j]).max(p[i].dist(p[k])).max(1e-9);
        if area < 1e-3 * scale * scale {
            return true;
        }
    }
    false
}

#[cfg(test)]
